import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) throws Exception {
        Class<?> readingType = Class.forName("Solution$Reading");
        Object reading = construct(readingType, "r-1", "Jöhn | Doe", 101, "120/80", 37.5);
        String label64 = Base64.getEncoder().encodeToString("Jöhn | Doe".getBytes(StandardCharsets.UTF_8));
        String pressure64 = Base64.getEncoder().encodeToString("120/80".getBytes(StandardCharsets.UTF_8));
        String encoded = (String) call("encode", reading);
        assertEquals("r-1|" + label64 + "|101|" + pressure64 + "|37.5", encoded);

        Object decoded = call("decode", encoded);
        assertEquals("r-1", property(decoded, "id"));
        assertEquals("Jöhn | Doe", property(decoded, "patientLabel", "label"));
        assertEquals(101, ((Number) property(decoded, "pulse")).intValue());
        assertEquals("120/80", property(decoded, "pressure"));
        assertEquals(37.5, ((Number) property(decoded, "temperature")).doubleValue());

        List<?> alerts = (List<?>) call("alerts", reading);
        assertEquals(List.of("pulse"), alerts);
        expect(UnsupportedOperationException.class, () -> ((List<Object>) alerts).add("x"));

        assertEquals(List.of(), call("alerts", construct(readingType, "ok", "Patient", 60, "120/80", 36.5)));
        assertEquals(List.of(), call("alerts", construct(readingType, "ok", "Patient", 100, "120/80", 37.5)));
        assertEquals(List.of("pulse", "pressure", "temperature"),
                call("alerts", construct(readingType, "bad", "Patient", 59, "121/80", 36.4)));
        assertEquals(List.of("pulse", "pressure", "temperature"),
                call("alerts", construct(readingType, "bad", "Patient", 101, "120/080", 37.6)));

        expect(NullPointerException.class, () -> call("encode", (Object) null));
        expect(NullPointerException.class, () -> call("decode", (Object) null));
        expect(NullPointerException.class, () -> call("alerts", (Object) null));
        expect(IllegalArgumentException.class, () -> call("decode", "a|b|1|c"));
        expect(IllegalArgumentException.class, () -> call("decode", "id|%%%|60|MTIwLzgw|37.0"));
        expect(IllegalArgumentException.class, () -> call("decode", "id|UGF0aWVudA==|x|MTIwLzgw|37.0"));
        expect(IllegalArgumentException.class, () -> call("decode", "id|UGF0aWVudA==|60|MTIwLzgw|x"));
        expect(IllegalArgumentException.class, () -> call("decode", " |UGF0aWVudA==|60|MTIwLzgw|37.0"));
        expect(IllegalArgumentException.class, () -> call("decode", "id|ICAg|60|MTIwLzgw|37.0"));

        for (Field field : readingType.getDeclaredFields()) {
            if (!field.isSynthetic() && !Modifier.isFinal(field.getModifiers())) {
                throw new AssertionError("Reading field is mutable: " + field.getName());
            }
        }
    }

    private static Object construct(Class<?> type, Object... arguments) {
        try {
            Constructor<?> constructor = type.getDeclaredConstructor(String.class, String.class, int.class, String.class, double.class);
            constructor.setAccessible(true);
            return constructor.newInstance(arguments);
        } catch (InvocationTargetException error) { throw rethrow(error.getCause()); }
        catch (Exception error) { throw new RuntimeException(error); }
    }

    private static Object call(String name, Object... arguments) {
        try {
            for (Method method : Solution.class.getMethods()) {
                if (method.getName().equals(name) && method.getParameterCount() == arguments.length) return method.invoke(null, arguments);
            }
            throw new AssertionError("missing method " + name);
        } catch (InvocationTargetException error) { throw rethrow(error.getCause()); }
        catch (ReflectiveOperationException error) { throw new RuntimeException(error); }
    }

    private static Object property(Object target, String... names) {
        for (String name : names) {
            try { return target.getClass().getMethod(name).invoke(target); }
            catch (NoSuchMethodException ignored) { }
            catch (Exception error) { throw new RuntimeException(error); }
        }
        throw new AssertionError("missing property accessor");
    }

    private static RuntimeException rethrow(Throwable error) {
        if (error instanceof RuntimeException) return (RuntimeException) error;
        if (error instanceof Error) throw (Error) error;
        return new RuntimeException(error);
    }

    private static void expect(Class<? extends Throwable> type, Runnable action) {
        try { action.run(); } catch (Throwable error) {
            if (type.isInstance(error)) return;
            throw new AssertionError("expected " + type.getName() + " but got " + error, error);
        }
        throw new AssertionError("expected " + type.getName());
    }

    private static void assertEquals(Object expected, Object actual) {
        if (expected instanceof Double && actual instanceof Double) {
            if (Double.compare((Double) expected, (Double) actual) == 0) return;
        } else if (expected.equals(actual)) return;
        throw new AssertionError("expected " + expected + " but got " + actual);
    }
}

